<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Profile extends MY_Controller {
 public function index(){ $c=$this->require_auth();if(!$c)return;$this->load->model('Account_model','accounts');if($this->input->method(TRUE)==='GET'){$u=$this->accounts->user($c['sub']);return $this->respond(array('userId'=>$u['id'],'displayName'=>$u['display_name'],'avatarUrl'=>$u['avatar_url'],'locale'=>$u['locale'],'timezone'=>$u['timezone'],'theme'=>$u['theme'],'bio'=>$u['bio']));}$d=$this->body();$set=array();$map=array('displayName'=>'display_name','avatarUrl'=>'avatar_url','locale'=>'locale','timezone'=>'timezone','theme'=>'theme','bio'=>'bio');foreach($map as $in=>$col)if(array_key_exists($in,$d))$set[$col]=$d[$in];if(isset($set['theme'])&&!in_array($set['theme'],array('dark','light','system'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid theme',422);if(isset($set['display_name'])&&(trim($set['display_name'])===''||strlen($set['display_name'])>100))return $this->fail('VALIDATION_ERROR','Invalid display name',422);if(isset($set['bio'])&&strlen($set['bio'])>2000)return $this->fail('VALIDATION_ERROR','Bio is too long',422);$this->accounts->update($c['sub'],$set);$u=$this->accounts->user($c['sub']);return $this->respond(array('userId'=>$u['id'],'displayName'=>$u['display_name'],'avatarUrl'=>$u['avatar_url'],'locale'=>$u['locale'],'timezone'=>$u['timezone'],'theme'=>$u['theme'],'bio'=>$u['bio'])); }
}
